import math
def priority(task, state, c=2.0, guard=1e6, spt_w=1.0, age_w=1.0, ten_boost=1.5, spt_hi=2.0, q_hi=10):
    est = max(task.estimated_runtime, 1e-6)
    ratio = (state.now - task.release) / est
    g = guard if ratio >= c else 0.0
    tier = ten_boost if task.tenant == 'premium' else 1.0
    # premium requests get SPT priority under load; otherwise aging dominates
    if state.queue_len >= q_hi and task.tenant == 'premium':
        return g + tier * spt_hi * spt_w / est
    return g + tier * (age_w * ratio + spt_w / est)  # tuned (c=1.79,guard=2.96e+05,spt_w=2.51,age_w=0.54,ten_boost=0.611,spt_hi=7.11,q_hi=24.3)
